mapper.insert:
INSERT INTO investigation (
    investigation_id, incident_id, status, aggregate_version, authority_service,
    authority_epoch, authority_active_from, active_run_id, updated_at
) VALUES (
    #{investigationId}, #{incidentId}, #{status}, #{version}, #{authorityEpoch.service},
    #{authorityEpoch.epoch}, #{authorityEpoch.activeFrom}, #{activeRunId}, #{updatedAt}
)

INSERT INTO investigation_budget (
    investigation_id, max_steps, max_tool_calls, max_tokens, max_duration_seconds,
    used_steps, used_tool_calls, used_tokens, used_duration_seconds, aggregate_version
) VALUES (
    #{investigationId}, #{budget.maxSteps}, #{budget.maxToolCalls}, #{budget.maxTokens},
    #{budget.maxDurationSeconds}, #{budget.usedSteps}, #{budget.usedToolCalls}, #{budget.usedTokens},
    #{budget.usedDurationSeconds}, #{version}
)

mapper.update:
UPDATE investigation
SET status = #{value.status}, aggregate_version = #{value.version},
    authority_service = #{value.authorityEpoch.service},
    authority_epoch = #{value.authorityEpoch.epoch},
    authority_active_from = #{value.authorityEpoch.activeFrom},
    active_run_id = #{value.activeRunId}, updated_at = #{value.updatedAt}
WHERE investigation_id = #{value.investigationId}
  AND aggregate_version = #{expectedVersion}

