INSERT INTO investigation_conclusion (
    conclusion_id, investigation_id, conclusion_type, summary_code, evidence_refs, concluded_at
) VALUES (
    #{conclusionId}, #{investigationId}, #{conclusionType}, #{summaryCode}, #{evidenceRefs}, #{concludedAt}
)

INSERT INTO investigation_progress (
    progress_id, investigation_id, run_id, progress_sequence, aggregate_version,
    status, stage_code, summary_code, occurred_at
) VALUES (
    #{progressId}, #{investigationId}, #{runId}, #{progressSequence}, #{aggregateVersion},
    #{status}, #{stageCode}, #{summaryCode}, #{occurredAt}
)

INSERT INTO investigation_audit (
    audit_id, investigation_id, action_code, outcome_code, aggregate_version, occurred_at
) VALUES (
    #{auditId}, #{investigationId}, #{actionCode}, #{outcomeCode}, #{aggregateVersion}, #{occurredAt}
)

mapper.select:
SELECT progress_id, investigation_id, run_id, progress_sequence, aggregate_version,
       status, stage_code, summary_code, occurred_at
FROM investigation_progress
WHERE investigation_id = #{investigationId} AND progress_sequence > #{sequenceExclusive}
ORDER BY progress_sequence
LIMIT #{limit}

