UPDATE diagnosis_publication_intent
SET topic_name = #{topic}, canonical_content = #{canonicalBytes},
    canonical_sha256 = #{canonicalSha256}, next_attempt_at = #{createdAt}
WHERE intent_id = #{intentId} AND event_id = #{eventId}
  AND investigation_id = #{investigationId}
  AND aggregate_version = #{aggregateVersion}
  AND aggregate_sequence = #{sequence}
  AND authority_epoch = #{authorityEpoch}
  AND canonical_sha256 IS NULL

